"""Live terminal frame for a wholly free Bundle, using explicit endpoint IDs."""
from . import boundary_quad_bridge_nodes as bridge


def frame(g,sources,paths,bundle_id):
    pos=g.node('GeometryNodeInputPosition','Original source endpoint coordinates').outputs[0]
    bundle=g.compare(g.named('st_path_bundle_id'),bundle_id,kind='INT')
    centers=[];checks=[]
    for side in (0,1):
        flags=[g.all(g.named('st_path_'+end+'_bundle_free','BOOLEAN'),
                     g.compare(g.named('st_path_'+end+'_bundle_side'),side,kind='INT')) for end in ('start','end')]
        selected=g.node('GeometryNodeSeparateGeometry','Explicit free '+('head' if side==0 else 'tail')+' members')
        selected.domain='POINT';g.set(paths,selected.inputs['Geometry'])
        g.set(g.all(bundle,g.either(*flags)),selected.inputs['Selection']);rows=selected.outputs['Selection']
        endpoint=g.switch(flags[0],g.math('SUBTRACT',g.math('ADD',g.named('st_path_start'),g.named('st_path_count')),1.),
                          g.named('st_path_start'),'INT')
        point=g.sample(sources,pos,endpoint,'FLOAT_VECTOR')
        centers.append(g.xyz(*(g.stat(rows,g.component(point,c),output='Mean') for c in ('X','Y','Z'))))
        checks.append(g.compare(bridge._size(g,rows),2))
    axis=g.vector('SUBTRACT',centers[1],centers[0])
    checks.append(g.compare(g.vector('LENGTH',axis),1e-4,'GREATER_THAN'))
    return axis,g.all(*checks)
